package br.com.livraria.autor.service; import br.com.livraria.autor.model.Autor; import br.com.livraria.autor.repository.AutorRepository; import br.com.livraria.autor.exception.RecursoNaoEncontradoException; import org.springframework.stereotype.Service; import java.util.List; @Service public class AutorService { private final AutorRepository repository; public AutorService(AutorRepository repository){this.repository=repository;} public List<Autor> listar(){return repository.findAll();} public Autor buscar(Long id){return repository.findById(id).orElseThrow(()->new RecursoNaoEncontradoException("Autor não encontrado: "+id));} public Autor salvar(Autor autor){return repository.save(autor);} public Autor atualizar(Long id,Autor dados){Autor autor=buscar(id);autor.setNome(dados.getNome());autor.setNacionalidade(dados.getNacionalidade());return repository.save(autor);} public void excluir(Long id){repository.delete(buscar(id));} }